public static int mostSick(Queue<CovidTest> q) {
    int bestCode = 0;
    int bestCount = 0;
    while (!q.isEmpty()) {
        CovidTest t = q.remove();
        if (t.getSick()) {
            // סופרים את החולים מהעיר של t, ומוציאים מהתור את כל הנבדקים של העיר הזו
            int code = t.getCityCode();
            int count = 1;
            Queue<CovidTest> rest = new Queue<CovidTest>();
            while (!q.isEmpty()) {
                CovidTest x = q.remove();
                if (x.getCityCode() == code) {
                    if (x.getSick()) {
                        count++;
                    }
                } else {
                    rest.insert(x);
                }
            }
            while (!rest.isEmpty()) {
                q.insert(rest.remove());
            }
            if (count > bestCount) {
                bestCount = count;
                bestCode = code;
            }
        }
    }
    return bestCode;
}

